static void party_wizard_cast205(Combat*g,CampaignFollower200*m){unsigned skill=m->pendingSkill;if((skill!=77&&skill!=80)||g->time<m->impactAt)return;m->pendingSkill=0;int slot=combat_field_slot(g);unsigned rank=m->pendingRank;if(slot<0||!rank||rank>10)return;float x=m->groundX205,y=m->groundY205;if(combat_dist(m->x,m->y,x,y)>skillDefs[skill].range||!party_line200(g,m->x,m->y,x,y)||!party_field_targets205(g,skill==80?1:4,x,y,skillDefs[skill].radius))return;unsigned cost=party_skill_base_cost201(skill,rank);if(m->sp<cost||!party_save_vital200(m,m->hp,m->sp-cost))return;unsigned intelligence=(unsigned)party_stat200(m,3,g->time),low=intelligence+(intelligence/7)*(intelligence/7),high=intelligence+(intelligence/5)*(intelligence/5),power=low+combat_random(g)%(high-low+1);CombatField*f=g->fields+slot;memset(f,0,sizeof(*f));f->companionOwner194=m->id+1;f->x=x;f->y=y;f->createdAt45=f->nextAt=g->time;f->secondId=(int)skill;f->rank=(int)rank;f->radius=skillDefs[skill].radius;f->remaining=f->expected=skill==80?10:4;f->power=(int)(power*(skill==80?100+40*rank:80+20*rank)/100);if(skill==80)combat_sound(g,SOUND_STORM_WIND180);}
